Dear all,<br><br>I am trying to create a function to add a combo box to a web page and<br>pass the field selected to R, and another function to enable the user<br>to pass an array to R, but both fail -at least: they dont totally<br>succeed.<br>I am putting my code at the bottom of this email, but here is what<br>happens:<br>For the combo box: my code generates a web page containing a combo box<br>with the two values &quot;a&quot; and &quot;b&quot;, just as I wanted. But when I click on<br>the &quot;submit&quot; button, NA is printed on the webpage instead of &quot;a&quot; or<br>&quot;b&quot;. it seems the variable &#39;listNames&#39; is lost somehow. Nothing<br>changes if I assign listNames as a global variable.<br><br>For the array of inputs: the value entered by the user are simply not<br>taken into account.<br><br>I would be grateful if someone could have a look. Otherwise, the Rook<br>package was simply failing with RStudio and sometimes it crashes my R<br>session - I am running R from Eclipse using StatET. Maybe there is<br>some compatibility problem with the rJava package.<br><br>Cheers,<br>Sam<br><br>Here is the code. There shouldnt be any dependancies so one could<br>simply copy/paste it into R.<br><br><br>#for the combo box:<br><br>generateComboBox&lt;-function(values,texts,which.selected=1,variable)<br>{<br>	res&lt;-&#39;&lt;form method=GET&gt;&lt;div&gt;
&#39;<br>	res&lt;-paste(res,&#39;&lt;select name=&quot;&#39;,variable,&#39;&quot;&gt;
&#39;,sep=&#39;&#39;)<br>	nChoices&lt;-length(values)<br>	for(i in 1:nChoices)<br>	{<br>		tmp&lt;-paste(&#39;&lt;option<br>value=&quot;&#39;,values[i],&#39;&quot;&#39;,ifelse(i==which.selected,&#39;<br>selected&#39;,&#39;&#39;),&#39;&gt;&#39;,&#39;&#39;,texts[i],&#39;&lt;/option&gt;
&#39;,sep=&#39;&#39;)<br>		res&lt;-paste(res,tmp,sep=&#39;&#39;)<br>	}<br>	res&lt;-paste(res,&#39;&lt;/select&gt;
&#39;)<br>	res&lt;-paste(res,&#39;&lt;div&gt;&lt;input type=&quot;submit&quot; value=&quot;submit&quot;&gt;&lt;/<br>div&gt;&#39;,sep=&#39;&#39;)<br>	res&lt;-paste(res,&#39;&lt;/form&gt;&#39;)<br>	return(res)<br>}<br><br><br>testComboBox&lt;-function(env)<br>{<br>	num&lt;-1<br>	listNames&lt;-c(&quot;a&quot;,&quot;b&quot;)<br>	req &lt;- Rook::Request$new(env)<br>	res &lt;- Rook::Response$new()<br><br>	if (!is.null(req$GET()[[&#39;num&#39;]]))<br>		num &lt;- req$GET()[[&#39;num&#39;]]<br>	res<br>$write(generateComboBox(1:2,listNames,which.selected=num,variable=&#39;num&#39;))<br>	res$write(listNames[num])<br>	res$finish()<br>}<br><br>s&lt;-Rhttpd$new()<br>#<br>#s$add(name=&#39;testPlot&#39;,app=&#39;appExample3.R&#39;)<br>s&lt;-Rhttpd$new()<br>s$add(name=&#39;testComboBox&#39;,app=testComboBox)<br>s$start(quiet=TRUE)<br>s$print()<br>s$browse(1)<br><br><br><br>#for the array of inputs:<br><br>generateArrayOfInputs&lt;-<br>function(ncols,nrows,colNames=NULL,rowNames=NULL,variable)<br>{<br>	res&lt;-&#39;&lt;form method=&quot;POST&quot;&gt;
&lt;table border=&quot;1&quot;&gt;
&#39;<br>	if(!is.null(colNames))<br>	{<br>		res&lt;-paste(res,&#39;&lt;TD&gt;&lt;/TD&gt;&#39;,sep=&#39;&#39;)<br>		for(j in 1:ncols)<br>		{<br>			res&lt;-paste(res,&#39;&lt;TD&gt; &#39;,colNames[j],&#39; &lt;/TD&gt;&#39;,sep=&#39;&#39;)<br>		}<br>	}<br>	for(i in 1:nrows)<br>	{<br>		res&lt;-paste(res,&#39;&lt;TR&gt;
&#39;,sep=&#39;&#39;)<br>		if(!is.null(rowNames))<br>		{<br>			res&lt;-paste(res,&#39;&lt;TD&gt; &#39;,rowNames[i],&#39; &lt;/TD&gt;&#39;)<br>		}<br>		for(j in 1:ncols)<br>		{<br>			res&lt;-<br>paste(res,&#39;&lt;TD&gt;&#39;,eval(parse(text=paste(variable,i,j,sep=&#39;_&#39;))),&#39;&lt;input<br>type=&quot;value&quot; NAME=&quot;&#39;,paste(variable,i,j,sep=&#39;_&#39;),&#39;&quot;/&gt;&lt;/TD&gt;&#39;,sep=&#39;&#39;)<br>		}<br>		res&lt;-paste(res,&#39;&lt;/TR&gt;
&#39;,sep=&#39;&#39;)<br>	}<br>	res&lt;-paste(res,&#39;&lt;/table&gt;
&#39;,sep=&#39;&#39;)<br>	res&lt;-paste(res,&#39;&lt;div&gt;&lt;input type=&quot;submit&quot; value=&quot;submit&quot;&gt;&lt;/<br>div&gt;&#39;,sep=&#39;&#39;)<br>	res&lt;-paste(res,&#39;&lt;/form&gt;&#39;)<br><br>	return(res)<br>}<br><br>testGrid&lt;-function(env)<br>{<br>	mat&lt;&lt;-matrix(1,ncol=3,nrow=10)<br>	for(i in 1:nrow(mat))<br>	{<br>		for(j in 1:ncol(mat))<br>		{<br>			eval(parse(text=paste(paste(&#39;mat&#39;,i,j,sep=&#39;_&#39;),&#39;&lt;&lt;-1&#39;,sep=&#39;&#39;)))<br><br>		}<br>	}<br><br><br><br>	req &lt;- Rook::Request$new(env)<br>	res&lt;-Rook::Response$new()<br><br>	for(i in 1:nrow(mat))<br>	{<br>		for(j in 1:ncol(mat))<br>		{<br>			if (!is.null(req$GET()[[paste(&#39;mat&#39;,i,j,sep=&#39;_&#39;)]]))<br>				eval(parse(text=paste(paste(&#39;mat&#39;,i,j,sep=&#39;_&#39;),&#39;&lt;- req$GET()<br>[[&#39;,paste(&#39;mat&#39;,i,j,sep=&#39;_&#39;),&#39;]]&#39;,sep=&#39;&#39;)))<br><br>		}<br>	}<br><br>	res<br>$write(generateArrayOfInputs(ncols=3,nrows=10,colNames=letters[1:3],rowNames=1:10,variable=&quot;mat&quot;))<br>	for(i in 1:nrow(mat))<br>	{<br>		for(j in 1:ncol(mat))<br>		{<br>			print(eval(parse(text=paste(&#39;mat&#39;,i,j,sep=&#39;_&#39;))))<br><br>		}<br>	}<br>	for(i in 1:nrow(mat))<br>	{<br>		for(j in 1:ncol(mat))<br>		{<br>	<br>eval(parse(text=paste(&#39;mat[&#39;,i,&#39;,&#39;,j,&#39;]&lt;&lt;-&#39;,paste(&#39;mat&#39;,i,j,sep=&#39;_&#39;),sep=&#39;&#39;)))<br><br>		}<br>	}<br>	res$write(sum(mat))<br>	res$finish()<br>}<br><br>s2&lt;-Rhttpd$new()<br>#<br>#s$add(name=&#39;testPlot&#39;,app=&#39;appExample3.R&#39;)<br>s2&lt;-Rhttpd$new()<br>s2$add(name=&#39;testGrid&#39;,app=testGrid)<br>s2$start(quiet=TRUE)<br>s2$print()<br>s2$browse(1)<br><br><br><br>
